import json

def get_logs(service=None, level=None, limit=200, offset=0):
    params = {}
    if service is not None:
        params['service'] = service
    if level is not None:
        params['level'] = level
    params['limit'] = limit
    params['offset'] = offset
    result = query_logs(**params)
    return result

def count_errors(service):
    # Count ERROR-level logs for a given service
    count = 0
    offset = 0
    limit = 200
    while True:
        result = get_logs(service=service, level='ERROR', limit=limit, offset=offset)
        items = result.get('items', [])
        count += len(items)
        if len(items) < limit:
            break
        offset += limit
    return count

services = ['api', 'auth', 'billing', 'search', 'worker']
error_counts = {}
for svc in services:
    error_counts[svc] = count_errors(svc)

max_service = max(error_counts, key=error_counts.get)
print(max_service)

