import os
import re

total_sum = 0
for root, dirs, files in os.walk('reports'):
    for file in files:
        if file.endswith('.txt'):  # assuming report files are .txt; adjust if needed
            filepath = os.path.join(root, file)
            with open(filepath, 'r') as f:
                for line in f:
                    if line.startswith('TOTAL:'):
                        # Extract the number after 'TOTAL:'
                        match = re.search(r'TOTAL:\s*(\d+)', line)
                        if match:
                            total_sum += int(match.group(1))
print(total_sum)

