def get_total_from_file(filepath):
    with open(filepath, 'r') as f:
        lines = f.readlines()
    for line in reversed(lines):
        if line.strip().startswith('TOTAL:'):
            try:
                return int(line.split(':')[1].strip())
            except ValueError:
                return None
    return None

def sum_totals(root_dir):
    total_sum = 0
    for dirpath, dirnames, filenames in os.walk(root_dir):
        for filename in filenames:
            if filename.endswith('.txt'):  # assuming report files are .txt
                filepath = os.path.join(dirpath, filename)
                total = get_total_from_file(filepath)
                if total is not None:
                    total_sum += total
    return total_sum

