def get_open_bug_assignees(repo):
    # Get all open issues with label 'bug' up to 1000 items (paging)
    offset = 0
    assignee_counts = {}
    while True:
        result = list_issues(repo=repo, state='open', label='bug', limit=100, offset=offset)
        items = result.get('items', [])
        if not items:
            break
        for issue in items:
            assignee = issue.get('assignee')
            if assignee:
                # assignee is a user id; look up name
                user_info = lookup_user(assignee)
                name = user_info.get('name', assignee)  # fallback to id if name not found
                assignee_counts[name] = assignee_counts.get(name, 0) + 1
        offset += 100
        if len(items) < 100:
            break
    # Find max count
    max_count = max(assignee_counts.values(), default=0)
    # Return any person with max count
    for name, count in assignee_counts.items():
        if count == max_count:
            return name
    return None

