def rollback_failed_deployments(service, env):
    offset = 0
    limit = 50
    while True:
        result = list_deployments(service=service, env=env, status='failed', limit=limit, offset=offset)
        items = result['items']
        if not items:
            break
        for item in items:
            if item['service'] == service and item['env'] == env and item['status'] == 'failed':
                print(f"Rolling back deployment {item['id']}")
                rollback_deployment(deployment_id=item['id'])
        offset += limit
        if len(items) < limit:
            break

